<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { useRouter } from 'vue-router'
import { useOverlay } from '../../composables/useOverlay'
import { useDemoStore } from '../../stores/demo'
import { highlight } from '../../demo/rag.js'
import DocumentDetailDialog from '../knowledge/DocumentDetailDialog.vue'
import { useKnowledgeStore } from '../../stores/knowledge'
import type { Chunk } from '../../types/models'
const {overlay,open,close}=useOverlay(), store=useDemoStore(), router=useRouter(), dialog=ref<HTMLElement>()
const knowledge = useKnowledgeStore()
let previous:HTMLElement|null=null, originalOverflow=''
const chunk=computed(()=>overlay.value?.chunk), doc=computed(()=>overlay.value?.doc || store.state.docs.find(d=>d.id===chunk.value?.docId))
const chunks=computed(()=>overlay.value?.kind==='document' && !doc.value?.persisted ? store.state.chunks.filter(c=>c.docId===doc.value?.id) : overlay.value?.chunks || [])
const index=computed(()=>overlay.value?.index ?? -1)
const subtitle=computed(()=>['chunk','preview'].includes(overlay.value?.kind || '') ? `${doc.value?.name || overlay.value?.subtitle || ''} · 第 ${chunk.value?.index} 段` : overlay.value?.subtitle)
const slim=computed(()=>['confirm','notice'].includes(overlay.value?.kind || '')), wide=computed(()=>['chunk','preview','document','help'].includes(overlay.value?.kind || ''))
function navigate(i:number) {const current=overlay.value;if(!current || !chunks.value[i])return;const c=chunks.value[i];open({...current,chunk:c,index:i,doc:current.documents?.find(d=>d.id===c.docId) || store.state.docs.find(d=>d.id===c.docId) || current.doc})}
function openChunk(c:Chunk) {open({kind:'chunk',title:'原文片段',chunk:c,doc:doc.value,chunks:chunks.value,index:chunks.value.findIndex(x=>x.id===c.id)})}
async function copy() {if(!chunk.value)return;try {await navigator.clipboard.writeText(chunk.value.text);store.notify('已复制原文片段')}catch {store.notify('复制失败，请手动选择文本','error')}}
function confirm() {const callback=overlay.value?.onOk;close();callback?.()}
function goChunk() {if(doc.value?.persisted)knowledge.selectedDocId=doc.value.id;close();void router.push('/chunk')}
function key(event:KeyboardEvent) {
  if(!overlay.value)return
  if(event.key==='Escape'){event.preventDefault();close();return}
  if(event.key==='Tab') {const focusables=dialog.value?.querySelectorAll<HTMLElement>('button:not([disabled]),a[href],input,select,textarea,[tabindex="0"]');if(!focusables?.length)return;const first=focusables[0],last=focusables[focusables.length-1];if(event.shiftKey && (document.activeElement===first || document.activeElement===dialog.value)){event.preventDefault();last.focus()}else if(!event.shiftKey && document.activeElement===last){event.preventDefault();first.focus()}}
}
watch(overlay,async(value,old)=>{if(value && !old){previous=document.activeElement as HTMLElement;originalOverflow=document.body.style.overflow;document.body.style.overflow='hidden'}if(value){await nextTick();dialog.value?.querySelector<HTMLElement>('button')?.focus()}else{document.body.style.overflow=originalOverflow;previous?.focus()} })
onMounted(()=>document.addEventListener('keydown',key));onBeforeUnmount(()=>{document.removeEventListener('keydown',key);document.body.style.overflow=originalOverflow})
const notices=[{t:'用药提醒',d:'今天 08:00 · 苯磺酸氨氯地平 5mg',badge:'待确认'},{t:'血压记录提醒',d:'今天 08:10 · 目标 < 150/90 mmHg',badge:'待完成'},{t:'社区助餐',d:'今天 11:30 · 和睦社区老年食堂',badge:'已预订'},{t:'家庭医生随访',d:'10-30 09:00 · 季度健康评估',badge:'待随访'}]
</script>
<template><Teleport to="body"><div id="modalRoot"><div v-if="overlay" class="modal-mask" @click.self="close"><div ref="dialog" class="modal" :class="{wide,slim}" role="dialog" aria-modal="true" aria-labelledby="dialog-title" tabindex="-1"><div class="modal-head"><div><h3 id="dialog-title">{{ overlay.title }}</h3><p v-if="subtitle">{{ subtitle }}</p></div><button class="modal-close" aria-label="关闭" @click="close"><AppIcon name="x" :size="16"/></button></div>
<div v-if="(overlay.kind==='chunk' || overlay.kind==='preview') && chunk" class="modal-body"><div class="orig-meta"><template v-if="overlay.kind==='chunk'"><span class="badge blue">{{ doc?.type || 'TXT' }}</span><span class="badge">来源：{{ doc?.source || '未知' }}</span><span class="badge">字符 {{ chunk.start }}–{{ chunk.start+chunk.chars }}</span><span class="badge">{{ chunk.chars }} 字</span><span class="badge" :class="chunk.vectorized?'green':'amber'">{{ chunk.vectorized?'已向量化':'未入库' }}</span></template><template v-else><span class="badge blue">第 {{ index+1 }} / {{ chunks.length }} 段</span><span class="badge">{{ chunk.chars }} 字</span><span class="badge">开始位置 {{ chunk.start }}</span><span class="badge">重叠 {{ store.state.chunkCfg.overlap }} 字</span></template></div><div class="original-text" v-html="highlight(chunk.text,overlay.query || '')"></div></div>
<DocumentDetailDialog v-else-if="overlay.kind==='document' && doc?.persisted" :doc="doc" :chunks="chunks" @open-chunk="openChunk"/>
<div v-else-if="overlay.kind==='document' && doc" class="modal-body"><div class="doc-detail-grid"><div v-for="[label,value] in [['文件类型',doc.type],['文件大小',doc.size],['上传时间',doc.uploadAt],['切块数量',`${chunks.length} 段`],['已入库',`${chunks.filter(c=>c.vectorized).length} 条`],['来源',doc.source || '本地上传']]" :key="label" class="kv"><span>{{ label }}</span><b>{{ value }}</b></div></div><div class="card-head" style="padding:0 0 10px;border:0"><b>文本片段</b><span class="sub">共 {{ chunks.length }} 段，点击查看原文</span></div><div style="max-height:320px;overflow:auto;border:1px solid var(--line);border-radius:10px"><button v-for="c in chunks.slice(0,30)" :key="c.id" class="chunk-row" @click="openChunk(c)"><span class="chunk-no">{{ c.index }}</span><div class="chunk-content"><div class="chunk-text">{{ c.text }}</div><div class="chunk-meta"><span>{{ c.chars }} 字</span><span>{{ c.vectorized?'已向量化':'未入库' }}</span></div></div></button><div v-if="!chunks.length" style="padding:24px;text-align:center;color:#92a0b5;font-size:12px">该文档尚未切块</div></div></div>
<div v-else-if="overlay.kind==='confirm'" class="modal-body"><p style="margin:0;font-size:13px;color:#4a5b73;line-height:1.8">{{ overlay.desc }}</p></div>
<div v-else-if="overlay.kind==='human'" class="modal-body"><div class="hint-box" style="margin-bottom:14px"><AppIcon name="info" :size="14"/><div>当前为原型演示，「转人工」不会真实外呼。生产环境可对接社区工单系统与呼叫中心。</div></div><div class="doc-detail-grid"><div v-for="[label,value] in [['服务主体','和睦社区养老服务中心'],['顾问','李顾问 · 工号 A1027'],['服务时间','08:30 – 17:30'],['联系电话','0571-8888 1027']]" :key="label" class="kv"><span>{{ label }}</span><b>{{ value }}</b></div></div><p style="font-size:12.5px;color:#6b7c95;line-height:1.8;margin:0">已将本次对话摘要（含 {{ overlay.desc }} 的问答与引用资料）整理为工单草稿，顾问接单后可直接查看上下文。</p></div>
<div v-else-if="overlay.kind==='help'" class="modal-body" style="font-size:13px;line-height:1.85;color:#3a4a63"><p style="margin-top:0"><b>1. 智能体（6 个）</b><br>左侧「智能体服务」下每个智能体都有独立菜单入口，进入后可提问；回答中的 <span class="cite" style="display:inline-flex">1</span> 编号对应右侧「参考知识」，点击可查看知识库原文。</p><p><b>2. RAG 全链路</b><br>知识库管理 → 文本切块 → 向量入库 → 向量检索 → 检索记录，五个环节都有独立菜单。上传文档后可完整走通一遍。</p><p><b>3. 数据说明</b><br>知识库管理和文本切块已接入后端与 MySQL，刷新后保留数据。向量入库和混合检索已接入真实模型与 FAISS，检索记录保存到数据库；智能体问答仍为独立演示。</p><p><b>4. 适老化</b><br>右上角「长辈模式」可放大字号、行高与点击区域。</p><div class="hint-box" style="margin-bottom:0"><AppIcon name="info" :size="14"/><div>建议演示路径：上传文档 → 切块 → 入库 → 检索 → 把问题抛给智能体 → 核对原文。</div></div></div>
<div v-else-if="overlay.kind==='notice'" class="modal-body" style="padding-top:8px"><div v-for="n in notices" :key="n.t" class="todo" style="padding:14px 4px"><span class="recent-ico" style="--tint:#EEF4FF;--c:#1B64F2"><AppIcon name="bell" :size="15"/></span><div class="todo-main"><b>{{ n.t }}</b><span>{{ n.d }}</span></div><span class="badge amber">{{ n.badge }}</span></div></div>
<div class="modal-foot"><template v-if="overlay.kind==='chunk' || overlay.kind==='preview'"><button v-if="index>0" class="btn" @click="navigate(index-1)">上一段</button><button v-if="index>=0 && index<chunks.length-1" class="btn" @click="navigate(index+1)">下一段</button><span style="flex:1"></span><button v-if="overlay.kind==='chunk'" class="btn" @click="copy"><AppIcon name="copy" :size="14"/> 复制原文</button></template><button v-if="overlay.kind==='document' && doc?.status !== 'failed' && !doc?.parsing" class="btn" @click="goChunk"><AppIcon name="scissors" :size="14"/> 去切块</button><template v-if="overlay.kind==='confirm'"><button class="btn" @click="close">取消</button><button class="btn primary" style="background:#e5484d;box-shadow:0 4px 12px rgba(229,72,77,.25);border-color:#e5484d" @click="confirm">{{ overlay.okText }}</button></template><template v-else-if="overlay.kind==='human'"><button class="btn" @click="close">取消</button><button class="btn primary" @click="close();store.notify('演示工单已生成，尚未接入社区工单系统')">提交工单</button></template><template v-else-if="overlay.kind==='notice'"><button class="btn" @click="close">关闭</button><button class="btn primary" @click="close();store.notify('已全部标记为已读')">全部标记已读</button></template><button v-else class="btn primary" @click="close">{{ overlay.kind==='help'?'知道了':'关闭' }}</button></div>
</div></div></div></Teleport></template>
